package org.sleepwell.app;

import androidx.activity.ComponentActivity;
import androidx.activity.OnBackPressedCallback;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.widget.*;
import java.util.UUID;

/** Exported review surface. Incoming values never become an unreviewed service Intent. */
public final class IncomingAutomationActivity extends ComponentActivity {
 private final SensitiveReviewTouches reviewTouches=new SensitiveReviewTouches();
 @Override public boolean dispatchTouchEvent(android.view.MotionEvent event){return reviewTouches.dispatch(this,event,super::dispatchTouchEvent);}
 private IncomingAutomation.Request request;private IncomingAutomation.Identity pinned;private IncomingAutomation.Grant grant;private IncomingAutomation.Work inspecting,preparing;
 private boolean resumed,terminal,submitted,inspected;private long received,sentAt,settingsRevision;private String owner=UUID.randomUUID().toString(),source="",issue="",resultStatus="",initialProcess=IncomingAutomation.PROCESS;
 private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_SECURE);getWindow().getDecorView().setFilterTouchesWhenObscured(true);receive(getIntent(),b);getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){@Override public void handleOnBackPressed(){cancel();}});render();}
 private void receive(Intent intent,Bundle b){try{request=IncomingAutomation.parse(this,intent);source=IncomingAutomation.verifiedCaller(this);received=SystemClock.elapsedRealtime();TrackingService.Snapshot snapshot=TrackingService.snapshot();pinned=snapshot==null?null:new IncomingAutomation.Identity(snapshot);
  if(b!=null){received=b.getLong("received",received);owner=b.getString("owner",owner);initialProcess=b.getString("process","");submitted=b.getBoolean("submitted");terminal=b.getBoolean("terminal");issue=b.getString("issue","");resultStatus=b.getString("status","");if(b.getBoolean("hasIdentity"))pinned=new IncomingAutomation.Identity(b.getLong("id"),b.getLong("start"),b.getBoolean("sonar"),b.getString("phase",""),b.getString("delay",""),b.getLong("admission"));else pinned=null;if(!IncomingAutomation.PROCESS.equals(initialProcess)||submitted&&!terminal){terminal=true;resultStatus="interrupted";issue="This request window was recreated after preparation. The command may have been accepted; it will not be replayed. Review tracking before making a new request.";}}
 }catch(RuntimeException invalid){request=null;terminal=true;resultStatus="rejected";issue=invalid.getMessage()==null?"The request is invalid.":invalid.getMessage();}setResult(java.util.Set.of("applied","already","staged").contains(resultStatus)?RESULT_OK:RESULT_CANCELED,IncomingAutomation.result(request,resultStatus.isEmpty()?"cancelled":resultStatus));}
 private String title(){return request==null?"Invalid tracking request":switch(request.command){case "START"->"Start tracking request";case "PAUSE"->"Pause tracking request";case "RESUME"->"Resume tracking request";default->"Stop tracking request";};}
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,title(),this::cancel);Design.space(body,18);if(request!=null){Design.text(body,source,13,400,Design.MUTED);Design.space(body,16);Design.text(body,request.command.equals("START")?"Review your actual tracking setup, then tap its Start button. This request cannot choose sensors, enable a microphone or bypass setup.":request.command.equals("STOP")?"End the displayed recording through its normal save and cleanup flow. This does not dismiss or change any alarm.":request.command.equals("PAUSE")?"Pause this recording through its normal capture-cleanup flow. Paused time remains a gap.":"Resume this paused recording with its original sensor and sound choices. Contactless resume still needs visible microphone admission.",15,400,Design.INK);Design.space(body,18);
   TrackingService.Snapshot current=TrackingService.snapshot();if(pinned==null)PlanActivity.detail(body,"tracking","Reviewed recording","No service was active when this request opened",null,null);else PlanActivity.detail(body,"tracking","Reviewed recording",pinned.sonar?"Contactless sensor":"Phone movement",pinned.phase,null);if(current!=null&&pinned!=null&&!pinned.same(current,true))Design.text(body,"The recording changed after this request opened.",13,500,Design.BROWN);Design.space(body,12);Design.text(body,"Every action needs your unlocked, visible confirmation. Requests expire after two minutes. No alarm, sound, volume or privacy settings can be supplied by the sender.",13,400,Design.MUTED);
  }
  IncomingAutomation.Settings settings=IncomingAutomation.settings(this);if(!settings.issue.isEmpty()){Design.space(body,12);Design.text(body,settings.issue,13,500,Design.BROWN);}if(!settings.enabled&&!terminal){Design.space(body,16);Design.text(body,"Incoming tracking requests are off.",16,600,Design.INK);Design.button(body,"Review incoming request settings",false,()->startActivity(new Intent(this,IncomingAutomationSettingsActivity.class)));}
  LinearLayout footer=RecordUi.footer(body);if(!issue.isEmpty())Design.text(footer,issue,13,500,Design.BROWN);if(!resultStatus.isEmpty())Design.text(footer,"Result: "+resultStatus,13,600,Design.INK);
  if(terminal){Design.button(footer,"Done",true,this::finish);}else{boolean busy=preparing!=null||grant!=null;String caption=busy?"Waiting for the owned operation…":inspecting!=null&&!inspecting.done?"Checking request receipt…":request!=null&&request.command.equals("START")?"Review setup; nothing starts yet":"Confirm "+(request==null?"request":request.command.toLowerCase(java.util.Locale.ROOT));Design.button(footer,caption,true,this::confirm).setEnabled(request!=null&&settings.enabled&&!busy&&(inspecting==null||inspecting.done));Design.button(footer,busy?"Close request window":"Cancel",false,this::cancel);}
 }
 private String guard(){if(request==null)return "rejected";if(!resumed||!hasWindowFocus()||isFinishing()||isDestroyed())return "not_visible";if(!IncomingAutomation.unlocked(this))return "locked";if(IncomingAutomation.alarmBusy(this))return "alarm_active";long now=SystemClock.elapsedRealtime();if(!IncomingAutomation.PROCESS.equals(initialProcess)||now<received||now-received>IncomingAutomation.REVIEW_TTL)return "stale";IncomingAutomation.Settings settings=IncomingAutomation.settings(this);if(!settings.enabled)return "disabled";TrackingService.Snapshot current=TrackingService.snapshot();if(request.command.equals("START"))return current==null&&!TrackingService.running?"":"stale";if(pinned==null)return current==null&&!TrackingService.running&&request.command.equals("STOP")?"already":"stale";return pinned.same(current,true)&&TrackingService.running?"":"stale";}
 private void confirm(){if(terminal||submitted||!inspected)return;String blocked=guard();if(!blocked.isEmpty()){complete(blocked,blocked.equals("already")?"No recording is active; nothing was changed.":"This request cannot act in the current unlocked recording state. Send a fresh request after reviewing tracking.");return;}TrackingService.Snapshot current=TrackingService.snapshot();
  if(request.command.equals("PAUSE")&&current!=null&&current.phase.equals("PAUSED")||request.command.equals("RESUME")&&current!=null&&current.phase.equals("ACTIVE")){complete("already","The recording is already in the requested state. Nothing was changed.");return;}
  if(!request.command.equals("START")&&(current==null||request.command.equals("PAUSE")&&!current.phase.equals("ACTIVE")||request.command.equals("RESUME")&&!current.phase.equals("PAUSED")||request.command.equals("STOP")&&!java.util.Set.of("ACTIVE","PAUSED","ARMED","DELAYED").contains(current.phase))){complete("stale","Tracking is transitioning or needs manual cleanup. Open tracking instead of replaying this request.");return;}
  if(permissionMissing(current)){complete("permission_required","Microphone access is unavailable. Review tracking setup; this request will not prompt for or enable capture permissions.");return;}
  settingsRevision=IncomingAutomation.settings(this).revision;submitted=true;preparing=IncomingAutomation.prepare(this,request,owner);issue="Preparing a private request receipt. Nothing has been sent yet.";render();poll();
 }
 private boolean permissionMissing(TrackingService.Snapshot current){return request!=null&&request.command.equals("RESUME")&&current!=null&&(current.sonar||current.soundsRequested||!current.automatic&&Prefs.flag(this,"noiseEnabled"))&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED;}
 private void poll(){if(!resumed||terminal)return;if(inspecting!=null&&inspecting.done){IncomingAutomation.Work prior=inspecting;inspecting=null;inspected=true;if(!prior.error.isEmpty()){complete("failed",prior.error);return;}if(!prior.state.isEmpty()){complete("duplicate",prior.state.equals("request_id_conflict")?"This request ID belongs to another command.":"This request was already prepared or handled ("+prior.state+"). It will not run again.");return;}render();}if(preparing!=null&&preparing.done){IncomingAutomation.Work work=preparing;preparing=null;if(!work.error.isEmpty()){complete("failed",work.error);return;}if(!work.created){complete("duplicate",work.state.equals("request_id_conflict")?"This request ID already belongs to a different command.":"This request ID was already prepared or handled ("+work.state+"). It will not run again.");return;}
   String blocked=guard();if(!blocked.isEmpty()||IncomingAutomation.settings(this).revision!=settingsRevision){complete(blocked.isEmpty()?"stale":blocked,"Confirmation ownership changed before dispatch. No new command was sent.");return;}TrackingService.Snapshot current=TrackingService.snapshot();if(permissionMissing(current)){complete("permission_required","Microphone permission changed before dispatch. Nothing was resumed.");return;}
   if(request.command.equals("START")){IncomingAutomation.record(this,request,owner,"staged");setResult(RESULT_OK,IncomingAutomation.result(request,"staged"));terminal=true;resultStatus="staged";try{startActivity(new Intent(this,TrackingActivity.class).putExtra(IncomingAutomation.START_NOTICE,true));finish();}catch(RuntimeException unavailable){complete("failed","Tracking setup could not be opened; nothing was started.");}return;}
   try{grant=IncomingAutomation.grant(this,request,pinned,owner,settingsRevision,()->resumed&&!isDestroyed()&&!isFinishing()&&hasWindowFocus());Intent command=TrackingActivity.controlIntent(this,request.command,current,true);command.putExtra(IncomingAutomation.DISPATCH,grant.token);if(request.command.equals("STOP")&&current!=null&&current.phase.equals("DELAYED"))command.putExtra("delayOwner",current.delayOwner);sentAt=SystemClock.elapsedRealtime();startService(command);issue="The command was sent once. Waiting for the actual recording state…";render();}catch(RuntimeException failed){IncomingAutomation.revoke(grant);complete("failed","Tracking could not accept this visible request. Open tracking to review the sensor and cleanup state.");return;}
  }
  if(grant!=null){TrackingService.Snapshot current=TrackingService.snapshot();if(!grant.issue.isEmpty()){complete("stale",grant.issue);return;}if(grant.accepted){boolean stopped=request.command.equals("STOP")&&current==null&&!TrackingService.running;boolean changed=!request.command.equals("STOP")&&pinned.same(current,false)&&(request.command.equals("PAUSE")&&current.phase.equals("PAUSED")||request.command.equals("RESUME")&&current.phase.equals("ACTIVE"));if(stopped||changed){String failure=Prefs.text(this,"trackingError","");complete(stopped&&!failure.isEmpty()?"needs_attention":"applied",stopped&&!failure.isEmpty()?"Tracking ended, but its saved record needs review in tracking/history.":"The requested recording state was observed. No alarm was changed.");return;}if(current!=null&&current.phase.equals("BLOCKED")){complete("needs_attention","Capture cleanup needs manual attention. No retry will be sent automatically.");return;}}
   if(SystemClock.elapsedRealtime()-sentAt>20000){complete(grant.accepted?"pending":"failed",grant.accepted?"The request was accepted but cleanup or transition is still pending. Review tracking; this request will not be repeated.":"No owned service acknowledgement was received. This request will not be replayed.");return;}}
  main.removeCallbacks(tick);main.postDelayed(tick,150);
 }
 private void complete(String result,String message){if(terminal&&resultStatus.equals("applied"))return;IncomingAutomation.revoke(grant);if(submitted&&request!=null)IncomingAutomation.record(this,request,owner,result);terminal=true;resultStatus=result;issue=message;setResult(java.util.Set.of("applied","already","staged").contains(result)?RESULT_OK:RESULT_CANCELED,IncomingAutomation.result(request,result));render();}
 private void cancel(){if(terminal){finish();return;}if(grant!=null&&grant.accepted)complete("pending","The command was already accepted. Closing does not undo it; review tracking for the final state.");else complete("cancelled","No further command will be sent from this request.");finish();}
 private final Runnable tick=this::poll;
 @Override protected void onResume(){super.onResume();resumed=true;if(request!=null&&!terminal&&IncomingAutomation.settings(this).enabled&&inspecting==null&&!inspected)inspecting=IncomingAutomation.inspect(this,request);render();poll();}
 @Override protected void onPause(){resumed=false;main.removeCallbacks(tick);if(grant!=null&&!grant.accepted){IncomingAutomation.revoke(grant);grant.issue="The request lost its visible window before service admission.";}if(preparing!=null&&!terminal){terminal=true;resultStatus="cancelled";issue="The confirmation window left the foreground before dispatch. Send a new request to continue.";IncomingAutomation.record(this,request,owner,"cancelled");setResult(RESULT_CANCELED,IncomingAutomation.result(request,"cancelled"));}super.onPause();}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);try{IncomingAutomation.parse(this,intent);}catch(RuntimeException ignored){}IncomingAutomation.revoke(grant);complete("rejected","A reused request window cannot accept a second request. Launch a fresh standard Activity request.");}
 @Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putLong("received",received);b.putString("owner",owner);b.putString("process",initialProcess);b.putBoolean("submitted",submitted);b.putBoolean("terminal",terminal);b.putString("issue",issue);b.putString("status",resultStatus);b.putBoolean("hasIdentity",pinned!=null);if(pinned!=null){b.putLong("id",pinned.id);b.putLong("start",pinned.start);b.putBoolean("sonar",pinned.sonar);b.putString("phase",pinned.phase);b.putString("delay",pinned.delay);b.putLong("admission",pinned.admission);}}
 @Override protected void onDestroy(){main.removeCallbacks(tick);IncomingAutomation.revoke(grant);super.onDestroy();}@Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){RecordUi.lightBars(this);if(resumed&&!terminal)poll();}}
}